/** 화면 그림(왼쪽 6.9) + 그림 아래 본문 + 오른쪽 단에 차례로 쌓기. fns 는 (x, y, w) → 아래쪽 y */
function shotCol(s, name, marks, under, ...fns) {
  const w = 6.9, x2 = L.X + w + G, w2 = L.R - x2, yb = TOP + shot(s, name, L.X, TOP, w, marks); if (under) body(s, L.X, yb + 0.1, w, under);
  return col(TOP, ...fns.map(f => y => f(x2, y, w2)));
}
